import sqlite3
ddl='''CREATE TABLE Clinic(cid INT PRIMARY KEY,city VARCHAR(20) NOT NULL);
CREATE TABLE Doctor(did INT PRIMARY KEY,licence CHAR(6) UNIQUE,cid INT REFERENCES Clinic(cid) ON DELETE SET NULL,fee INT CHECK(fee BETWEEN 200 AND 2000));
INSERT INTO Clinic VALUES(1,'Pune'),(2,'Agra');INSERT INTO Doctor VALUES(10,'L-0001',1,500),(11,'L-0002',2,800);'''
S={'A':"INSERT INTO Doctor VALUES (12,NULL,1,NULL)",'B':"INSERT INTO Doctor VALUES (13,'L-0003',NULL,2000)",'C':"DELETE FROM Clinic WHERE cid=2",'D':"UPDATE Clinic SET cid=5 WHERE cid=1"}
for k,s in S.items():
    c=sqlite3.connect(':memory:');c.execute('PRAGMA foreign_keys=ON');c.executescript(ddl)
    try: c.execute(s);c.commit();print(k,'ok')
    except sqlite3.IntegrityError as e: print(k,'fails',e)
# A ok, B ok, C ok, D fails (FOREIGN KEY constraint failed)
